package app.kinnect.audit;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import android.graphics.*;import android.media.*;import org.json.*;import java.io.*;import java.lang.reflect.*;import java.util.*;import java.util.concurrent.atomic.*;
public final class AdminBalanceAudit extends Instrumentation {
 volatile Activity resumed;int checks;JSONObject fixture;Object api;String theme;
 public void onCreate(Bundle b){super.onCreate(b);start();}public void callActivityOnResume(Activity a){super.callActivityOnResume(a);resumed=a;}
 void check(boolean b,String m){if(!b)throw new AssertionError(m);checks++;}Object get(Object o,String n)throws Exception{Field f=o.getClass().getDeclaredField(n);f.setAccessible(true);return f.get(o);}void set(Object o,String n,Object v)throws Exception{Field f=o.getClass().getDeclaredField(n);f.setAccessible(true);f.set(o,v);}Object call(Object o,String n,Class[] t,Object...v)throws Exception{Method m=o.getClass().getDeclaredMethod(n,t);m.setAccessible(true);return m.invoke(o,v);}
 Activity open(String name)throws Exception{resumed=null;getTargetContext().startActivity(new Intent().setClassName("app.kinnect.live","app.kinnect.live."+name).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));for(int n=0;n<100;n++){if(resumed!=null&&resumed.getClass().getName().endsWith(name)){call(api,"configure",new Class[]{String.class},"https://127.0.0.1:9");return resumed;}Thread.sleep(100);}throw new AssertionError("No Activity "+name);}
 View find(View v,String s){if(s.equals(v.getTag())||s.contentEquals(v.getContentDescription()==null?"":v.getContentDescription())||v instanceof TextView&&s.contentEquals(((TextView)v).getText()))return v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){View result=find(((ViewGroup)v).getChildAt(i),s);if(result!=null)return result;}return null;}
 void click(View v){check(v!=null,"Missing button");View item=v;while(!item.isClickable()&&item.getParent() instanceof View)item=(View)item.getParent();final View target=item;runOnMainSync(()->target.performClick());}
 void shot(Activity a,String name)throws Exception{String wanted=name.contains("wallet")?"Xu tặng":name.contains("gifts")?"Quà Live":null;if(wanted!=null)for(int n=0;n<40;n++){android.view.accessibility.AccessibilityNodeInfo window=getUiAutomation().getRootInActiveWindow();if(window!=null&&!window.findAccessibilityNodeInfosByText(wanted).isEmpty())break;Thread.sleep(100);}Thread.sleep(1400);try(FileOutputStream out=new FileOutputStream(new File(a.getExternalFilesDir(null),name))){getUiAutomation().takeScreenshot().compress(Bitmap.CompressFormat.PNG,100,out);}}
 void bounds(View v){if(v.getVisibility()!=View.VISIBLE)return;if(v instanceof TextView){TextView t=(TextView)v;if(t.getLayout()!=null&&t.getWidth()>0&&t.getHeight()>0){check(t.getLayout().getHeight()<=t.getHeight()-t.getPaddingTop()-t.getPaddingBottom()+2,"Text height clipped: "+t.getText());for(int n=0;n<t.getLineCount();n++)check(t.getLayout().getLineWidth(n)<=t.getWidth()-t.getPaddingLeft()-t.getPaddingRight()+2,"Text width clipped: "+t.getText());}}if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)bounds(((ViewGroup)v).getChildAt(i));}
 public void onStart(){Bundle out=new Bundle();Activity active=null;try{ClassLoader cl=getTargetContext().getClassLoader();api=cl.loadClass("app.kinnect.live.NativeApi").getField("shared").get(null);try(InputStream in=getContext().getAssets().open("admin34-fixture.json")){ByteArrayOutputStream bytes=new ByteArrayOutputStream();byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1)bytes.write(b,0,n);fixture=new JSONObject(bytes.toString("UTF-8"));}theme=getTargetContext().getSharedPreferences("kinnect_settings",0).getString("theme","auto");
 for(String variant:new String[]{"light","dark"}){getTargetContext().getSharedPreferences("kinnect_settings",0).edit().putString("theme",variant).commit();active=open("WalletActivity");final Activity wallet=active;for(int type=0;type<3;type++){final int mode=type;JSONObject state=new JSONObject().put("giftedCoins",mode==2?1234567890123L:2000).put("trialCoins",2000).put("purchasedCoins",mode==2?999999999999L:5000).put("unlimitedCoins",mode==1).put("withdrawableVnd",507500).put("earningsVnd",7500).put("vndPerCoin",100);runOnMainSync(()->{try{call(wallet,"draw",new Class[]{JSONObject.class},state);}catch(Exception e){throw new RuntimeException(e);}});Thread.sleep(150);bounds(wallet.getWindow().getDecorView());check(find(wallet.getWindow().getDecorView(),"wallet:balance")!=null,"Unified wallet card missing");if(mode==1)check(((TextView)find(wallet.getWindow().getDecorView(),"wallet:coins")).getText().toString().contains("∞"),"Admin infinity missing");else{View paid=find(wallet.getWindow().getDecorView(),"wallet:purchased"),gifted=find(wallet.getWindow().getDecorView(),"wallet:coins");check(paid.getTop()==gifted.getTop(),"Balances not aligned");check(paid.getParent()!=gifted.getParent(),"Balances not in separate columns");}shot(wallet,"admin34-wallet-"+mode+"-"+variant+".png");}
 runOnMainSync(()->wallet.finish());active=open("StoreActivity");final Activity store=active;for(int type=0;type<2;type++){final int mode=type;JSONObject catalog=new JSONObject(fixture.getJSONObject("store").toString());catalog.put("adminAccess",mode==1).put("unlimitedCoins",mode==1).put("trialCoins",2000).put("purchasedCoins",5000);if(mode==1){JSONArray owned=new JSONArray();JSONArray plans=catalog.getJSONArray("packages");for(int n=0;n<plans.length();n++)owned.put(plans.getJSONObject(n).getString("id"));catalog.put("ownedPackages",owned);catalog.put("owned",new JSONArray().put("kinnect_studio_pro"));catalog.put("liveGameUntil",253402300799000L);catalog.put("studioProUntil",253402300799000L);}runOnMainSync(()->{try{set(store,"catalog",catalog);call(store,"draw",new Class[]{});}catch(Exception e){throw new RuntimeException(e);}});Thread.sleep(150);check(find(store.getWindow().getDecorView(),mode==1?"store:unlimited":"store:balance:purchasedCoins")!=null,"Store balance state wrong");for(String tab:new String[]{"style","studio","live","gifts","member","owned"}){runOnMainSync(()->{try{call(store,"selectTab",new Class[]{String.class},tab);}catch(Exception e){throw new RuntimeException(e);}});Thread.sleep(100);bounds(store.getWindow().getDecorView());}runOnMainSync(()->{try{call(store,"selectTab",new Class[]{String.class},"style");}catch(Exception e){throw new RuntimeException(e);}});shot(store,"admin34-store-"+mode+"-"+variant+".png");if(mode==1){JSONObject p=catalog.getJSONArray("packages").getJSONObject(0);runOnMainSync(()->{try{call(store,"showPlan",new Class[]{JSONObject.class},p);}catch(Exception e){throw new RuntimeException(e);}});Thread.sleep(150);android.view.accessibility.AccessibilityNodeInfo window=getUiAutomation().getRootInActiveWindow();check(!window.findAccessibilityNodeInfosByText("Mua gói · ∞ xu").isEmpty(),"Admin cannot optionally buy");shot(store,"admin34-admin-buy.png");getUiAutomation().executeShellCommand("input keyevent 4").close();Thread.sleep(100);}}
 runOnMainSync(()->store.finish());}out.putString("result","PASS "+checks+":one compact paid/gifted balance,admin infinity optional purchase,large balances,six shop tabs,light/dark320dp;no public writes");finish(Activity.RESULT_OK,out);
 }catch(Throwable e){out.putString("error",e.toString());finish(Activity.RESULT_CANCELED,out);}finally{final Activity last=active;runOnMainSync(()->{if(last!=null)last.finish();});getTargetContext().getSharedPreferences("kinnect_settings",0).edit().putString("theme",theme==null?"auto":theme).commit();}}
}
